          left: Math.round(r.left*10)/10,
          width: Math.round(r.width*10)/10,
          path: (() => {
            let p=[], n=el, i=0;
            while(n && i<6){ p.push(n.tagName+(n.id?'#'+n.id:'')+(n.className&&typeof n.className==='string'?'.'+n.className.split(' ')[0]:'')); n=n.parentElement; i++; }
            return p.join('<');
          })()
        });
      }
    });
    // Check assistive inner HTML sizes via scrollWidth
    const assistiveDetail = [...document.querySelectorAll('#layersSection mjx-assistive-mml')].map(el => {
      const math = el.querySelector('math');
      const mr = math?.getBoundingClientRect();
      return {
        scrollW: el.scrollWidth,
        clientW: el.clientWidth,
        mathRight: mr ? Math.round(mr.right*10)/10 : null,
        mathWidth: mr ? Math.round(mr.width*10)/10 : null,
        mathPast: mr ? mr.right > winW + 0.5 : false,
