node <<'JS'
const { chromium } = require('/tmp/gnhf-pw/node_modules/playwright');
const path = require('path');
const root = '/Users/sinchunyeung/github/simplification-of-trajectory-streams';
(async () => {
  const browser = await chromium.launch({ headless: true, channel: 'chrome' });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  await page.goto('http://127.0.0.1:5050/?t=' + Date.now(), { waitUntil: 'networkidle' });
  await page.evaluate(() => {
    try { localStorage.setItem('simplify-viewer-tour-v1', '1'); } catch {}
    const tour = document.getElementById('uiTour');
    if (tour) { tour.hidden = true; tour.style.display='none'; }
  });
  const trigger = await page.$('.preloaded-trigger, #preloadedTrigger');
  if (trigger) {
    await trigger.click();
    await page.waitForTimeout(200);
    const opt = await page.$('[data-value="1"], .preloaded-option, .trace-picker-item');
    if (opt) await opt.click();
  } else {
    await page.selectOption('#traceSelect', '1').catch(()=>{});
  }
  await page.click('#loadBtn');
  await page.waitForFunction(() => (document.querySelector('#uploadStatus')?.textContent || '').includes('Loaded') || document.body.classList.contains('playback-ready'), { timeout: 180000 });
  await page.waitForTimeout(800);
  const layersToggle = await page.$('#mobileLayersToggle');
  if (layersToggle) await layersToggle.click();
  await page.evaluate(() => { const acc = document.getElementById('accordionSimplify'); if (acc) acc.open = true; });
  await page.waitForTimeout(400);
  const info = await page.evaluate(() => ({
    scrollW: document.documentElement.scrollWidth,
    assistiveCount: document.querySelectorAll('mjx-assistive-mml').length,
    // mobile may skip MathJax typeset
    mjxCount: document.querySelectorAll('#layersSection mjx-container').length,
    glosses: [...document.querySelectorAll('#toggle-Gi,#toggle-F,#toggle-F-Si,#toggle-S,#toggle-P')].map(cb => {
      const lab = cb.closest('label');
      return lab?.innerText.replace(/\s+/g,' ').trim() || lab?.textContent.replace(/\s+/g,' ').trim();
    }),
  }));
  console.log(JSON.stringify(info, null, 2));
  await page.screenshot({ path: path.join(root, 'web/usability/desktop-layer-glosses-390-regression-live.png'), fullPage: false });
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
